const user = $input.first().json.user;
const appUrl = 'http://localhost:5173';
return [{
  json: {
    to: user.email,
    subject: `Welcome to Nourishly, ${user.username}! 🥗`,
    html: `
      <div style="font-family:Inter,sans-serif;max-width:600px;margin:0 auto;padding:32px;background:#f0fdf4;border-radius:16px">
        <h1 style="color:#16a34a;font-size:28px;margin-bottom:8px">Welcome to Nourishly! 🥗</h1>
        <p style="color:#374151;font-size:16px">Hi <strong>${user.username}</strong>,</p>
        <p style="color:#374151">You've joined a community of home cooks sharing real, practical recipes for modern families.</p>
        <div style="background:white;border-radius:12px;padding:24px;margin:24px 0;border:1px solid #bbf7d0">
          <h2 style="color:#15803d;font-size:18px;margin-bottom:12px">Get started in 3 steps:</h2>
          <p>🍽️ <strong>Browse</strong> the feed and discover recipes</p>
          <p>🔖 <strong>Save</strong> your favourites to your library</p>
          <p>✨ <strong>Post</strong> your own recipe with AI assistance</p>
        </div>
        <a href="${appUrl}" style="display:inline-block;background:#16a34a;color:white;padding:12px 28px;border-radius:12px;text-decoration:none;font-weight:600">Start Cooking →</a>
        <p style="color:#9ca3af;font-size:12px;margin-top:32px">Nourishly — Cook Better. Live Better.</p>
      </div>
    `
  }
}];
